### Description
This Terraform program configures a Route 53 hosted zone named "primary" and an Elastic Load Balancer (ELB) named "main". It then creates a Route 53 record of type "A" with the name "www" that points to the ELB using an alias. The configuration ensures that the dependencies between the resources are correctly handled through Terraform references.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_route53_zone" "primary" {
  name = "primary.example.com"
}

resource "aws_elb" "main" {
  name               = "main"
  availability_zones = ["us-west-2a", "us-west-2b", "us-west-2c"]

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
  }
}

resource "aws_route53_record" "www" {
  name    = "www"
  type    = "A"
  zone_id = aws_route53_zone.primary.zone_id

  alias {
    name                   = aws_elb.main.dns_name
    zone_id                = aws_elb.main.zone_id
    evaluate_target_health = true
  }
}
```

This configuration sets up a basic infrastructure where:
- A Route 53 hosted zone named "primary.example.com" is created.
- An Elastic Load Balancer named "main" is configured with listeners and health checks.
- A Route 53 record named "www" is created to point to the ELB using an alias, ensuring that the DNS resolution is handled correctly.

