This Terraform program configures Route 53 to route different database endpoints to internal versus external users. It creates two Route 53 zones named "private.example.com" and "public.example.com". It also sets up two RDS instances, one internal and one public, and creates corresponding DNS records in each zone.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = [aws_subnet.private.id, aws_subnet.public.id]
}

resource "aws_db_instance" "internal_db" {
  identifier         = "internal"
  instance_class     = "db.t3.micro"
  allocated_storage  = 20
  engine             = "mysql"
  engine_version     = "8.0"
  username           = "admin"
  password           = "password"
  db_subnet_group_name = aws_db_subnet_group.main.name
  skip_final_snapshot = true
}

resource "aws_db_instance" "public_db" {
  identifier         = "public"
  instance_class     = "db.t3.micro"
  allocated_storage  = 20
  engine             = "mysql"
  engine_version     = "8.0"
  username           = "admin"
  password           = "password"
  publicly_accessible = true
  skip_final_snapshot = true
}

resource "aws_route53_zone" "private_zone" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public_zone" {
  name = "public.example.com"
}

resource "aws_route53_record" "internal_record" {
  name    = "db"
  type    = "A"
  zone_id = aws_route53_zone.private_zone.zone_id
  records = [aws_db_instance.internal_db.endpoint]
  ttl     = 300
}

resource "aws_route53_record" "public_record" {
  name    = "db"
  type    = "A"
  zone_id = aws_route53_zone.public_zone.zone_id
  records = [aws_db_instance.public_db.endpoint]
  ttl     = 300
}
```

