Description:
The Terraform program defines a Route 53 hosted zone named "main.example.com" and three DNS records: "primary", "replica-1", and "replica-2". The "primary" record points to a primary database instance, while "replica-1" and "replica-2" are configured with a weighted routing policy to split traffic between two replica database instances. Each record has a TTL of 300 seconds.

Terraform HCL Program:
```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "main" {
  name = "main.example.com"
}

resource "aws_route53_record" "primary" {
  name    = "primary"
  type    = "CNAME"
  zone_id = aws_route53_zone.main.zone_id
  ttl     = 300
  records = ["primary-db-instance.example.com"]
}

resource "aws_route53_record" "replica_1" {
  name    = "replica-1"
  type    = "CNAME"
  zone_id = aws_route53_zone.main.zone_id
  ttl     = 300
  records = ["replica-1-db-instance.example.com"]

  weighted_routing_policy {
    weight = 50
  }

  set_identifier = "replica-1"
}

resource "aws_route53_record" "replica_2" {
  name    = "replica-2"
  type    = "CNAME"
  zone_id = aws_route53_zone.main.zone_id
  ttl     = 300
  records = ["replica-2-db-instance.example.com"]

  weighted_routing_policy {
    weight = 50
  }

  set_identifier = "replica-2"
}
```

This configuration ensures that the weighted routing policy is correctly applied to the replica records by adding the `set_identifier` attribute, which is required when using the `weighted_routing_policy` block.

