  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_api_app" {
  name = "my_api_app"
}

# VPC
resource "aws_vpc" "my_api_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Subnet
resource "aws_subnet" "my_api_subnet" {
  vpc_id            = aws_vpc.my_api_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Auto Scaling Group
resource "aws_autoscaling_group" "my_api_asg" {
  name                 = "my_api_asg"
  launch_configuration = "my_api_lc"
  min_size             = 1
  max_size             = 3
  vpc_zone_identifier  = [aws_subnet.my_api_subnet.id]

  tag {
    key                 = "Name"
    value               = "my_api_asg"
    propagate_at_launch = true
  }

  # CPU Utilization-based Autoscaling Policy
  lifecycle {
    create_before_destroy = true
  }

  initial_lifecycle_hook {
    name                 = "before-instance-terminate"
    default_result       = "CONTINUE"
    heartbeat_timeout    = 300
    lifecycle_transition = "autoscaling:EC2_INSTANCE_TERMINATING"
  }
}

# Elastic Beanstalk Environment
