### Description of the Terraform Program

This Terraform program configures production and staging Elastic Beanstalk environments with respective RDS database instances. It includes the creation of an IAM role and instance profile named "eb_ec2_profile". The RDS instances are named "prod_db" for production and "staging_db" for staging. The Elastic Beanstalk application and environments are also configured accordingly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role and Instance Profile
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# RDS Instances
resource "aws_db_instance" "prod_db" {
  identifier       = "prod-db"
  engine           = "mysql"
  engine_version   = "8.0"
  instance_class   = "db.t3.micro"
  allocated_storage = 20
  username         = "admin"
  password         = "password123"
  skip_final_snapshot = true
}

resource "aws_db_instance" "staging_db" {
  identifier       = "staging-db"
  engine           = "mysql"
  engine_version   = "8.0"
  instance_class   = "db.t3.micro"
  allocated_storage = 20
  username         = "admin"
  password         = "password123"
  skip_final_snapshot = true
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name = "elastic_beanstalk_app"
}

# Elastic Beanstalk Environments
resource "aws_elastic_beanstalk_environment" "production_env" {
  name                = "production_env"
  application         = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceIdentifier"
    value     = aws_db_instance.prod_db.identifier
  }
}

resource "aws_elastic_beanstalk_environment" "staging_env" {
  name                = "staging_env"
  application         = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceIdentifier"
    value     = aws_db_instance.staging_db.identifier
  }
}
```

