Description:
The Terraform program configures an Elastic Beanstalk environment with autoscaling settings based on CPU utilization and connects it to an RDS database. The instance profile is named "eb_ec2_profile" and the database is named "my_db1". The program includes necessary IAM roles, policies, security groups, and other configurations to ensure proper setup.

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EC2 instances
resource "aws_iam_role" "ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for RDS access
resource "aws_iam_policy" "rds_access_policy" {
  name        = "rds_access_policy"
  description = "Policy to allow access to RDS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the RDS access policy to the EC2 role
resource "aws_iam_role_policy_attachment" "rds_access_policy_attachment" {
  policy_arn = aws_iam_policy.rds_access_policy.arn
  role       = aws_iam_role.ec2_role.name
}

# Instance Profile for EC2 instances
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.ec2_role.name
}

# RDS Parameter Group
resource "aws_db_parameter_group" "db_parameter_group" {
  name   = "my_db1-parameter-group"
  family = "mysql5.6"
}

# RDS Instance
resource "aws_db_instance" "my_db1" {
  identifier           = "my_db1"
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "5.6"
  username             = "admin"
  password             = "password"
  parameter_group_name = aws_db_parameter_group.db_parameter_group.name
  skip_final_snapshot  = true
}

# Security Group for RDS
resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  description = "Security group for RDS"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Replace with your CIDR block
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Auto Scaling Group
resource "aws_autoscaling_group" "autoscaling_group" {
  name                 = "my-elastic-beanstalk-asg"
  launch_configuration = "my-launch-config"  # Replace with your launch configuration name
  min_size             = 1
  max_size             = 3
  vpc_zone_identifier  = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs

  tag {
    key                 = "Name"
    value               = "my-elastic-beanstalk-asg"
    propagate_at_launch = true
  }
}

# Launch Configuration (assuming it's already created)
resource "aws_launch_configuration" "my_launch_config" {
  name          = "my-launch-config"
  image_id      = "ami-0c55b159cbfafe1f0"  # Replace with your AMI ID
  instance_type = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.eb_ec2_profile.name
}
```

