resource "aws_route53_health_check" "myapp_blue_health_check" {
  type              = "HTTP"
  fqdn              = "blue.myapp.com"
  port              = 80
  resource_path     = "/"
  failure_threshold = 3
}

resource "aws_route53_health_check" "myapp_green_health_check" {
  type              = "HTTP"
  fqdn              = "green.myapp.com"
  port              = 80
  resource_path     = "/"
  failure_threshold = 3
}

resource "aws_route53_record" "myapp_blue_record" {
  name    = "blue"
  zone_id = aws_route53_zone.myapp_zone.zone_id
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.myapp_blue_health_check.id

  records = ["192.168.1.1"]  # Replace with actual IP address
}

resource "aws_route53_record" "myapp_green_record" {
  name    = "green"
  zone_id = aws_route53_zone.myapp_zone.zone_id
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.myapp_green_health_check.id

  records = ["192.168.1.2"]  # Replace with actual IP address
}
