### Description
This Terraform program creates an Elastic Beanstalk application along with an IAM role and a configuration template. The IAM role is assumed by EC2 instances to manage Elastic Beanstalk environments. The configuration template specifies the solution stack and other settings for deploying applications on Elastic Beanstalk.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "beanstalk_service_role" {
  name = "beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name = "my-elastic-beanstalk-app"

  appversion_lifecycle {
    service_role = aws_iam_role.beanstalk_service_role.arn
    max_count    = 12
    max_age_in_days = 365
    delete_source_from_s3 = true
  }
}

resource "aws_elastic_beanstalk_configuration_template" "elastic_beanstalk_template" {
  name = "my-elastic-beanstalk-template"
  application = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  solution_stack_name = "64bit Amazon Linux 2015.09 v2.0.8 running Go 1.4"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name = "InstanceType"
    value = "t2.micro"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name = "EnvironmentType"
    value = "LoadBalanced"
  }
}
```

