### Description
The Terraform program defines an AWS Lex bot for ordering pizza with a follow-up question. It includes an IAM role for the Lambda function, the Lambda function itself, an AWS Lex intent, and the AWS Lex bot. The Lambda function is triggered by the Lex intent for fulfillment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "order_pizza_lambda" {
  function_name = "order_pizza_lambda"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_execution_role.arn
  filename      = "lambda_function_payload.zip"

  source_code_hash = filebase64sha256("lambda_function_payload.zip")
}

resource "aws_lex_intent" "order_pizza" {
  name = "OrderPizza"

  fulfillment_activity {
    type = "CodeHook"
    code_hook {
      message_version = "1"
      uri             = aws_lambda_function.order_pizza_lambda.invoke_arn
    }
  }

  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order me a pizza"
  ]
}

resource "aws_lex_slot_type" "pizza_size" {
  name = "PizzaSize"

  enumeration_value {
    value = "Small"
  }

  enumeration_value {
    value = "Medium"
  }

  enumeration_value {
    value = "Large"
  }
}

resource "aws_lex_slot" "size_slot" {
  name         = "SizeSlot"
  slot_type    = aws_lex_slot_type.pizza_size.name
  slot_type_version = "$LATEST"
  slot_constraint = "Required"
}

resource "aws_lex_intent" "order_pizza_followup" {
  name = "OrderPizzaFollowup"

  slot {
    name         = aws_lex_slot.size_slot.name
    slot_type    = aws_lex_slot.size_slot.slot_type
    slot_type_version = aws_lex_slot.size_slot.slot_type_version
    slot_constraint = aws_lex_slot.size_slot.slot_constraint
  }

  fulfillment_activity {
    type = "CodeHook"
    code_hook {
      message_version = "1"
      uri             = aws_lambda_function.order_pizza_lambda.invoke_arn
    }
  }

  sample_utterances = [
    "What size would you like?",
    "Can you specify the size?",
    "Tell me the size please."
  ]
}

resource "aws_lex_bot" "order_pizza_bot" {
  name           = "OrderPizzaBot"
  child_directed = false

  intent {
    intent_name  = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }

  intent {
    intent_name  = aws_lex_intent.order_pizza_followup.name
    intent_version = aws_lex_intent.order_pizza_followup.version
  }
}
```

This configuration creates an AWS Lex bot that first asks the user if they want to order a pizza and then follows up with a question about the size of the pizza. The Lambda function is triggered for both intents to handle the fulfillment logic.

