The Terraform program defines an AWS Lex bot for booking a trip. It includes an IAM role, a Lambda function, an AWS Lex intent, and the AWS Lex bot itself. The intent is configured with a dialog code hook pointing to the Lambda function, and the bot is linked to this intent. The program ensures all required attributes are filled and adheres to the AWS provider schema.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "book_trip_role" {
  name = "book_trip_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "book_trip_lambda" {
  function_name = "book_trip_lambda"
  role          = aws_iam_role.book_trip_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function.zip"

  environment {
    variables = {
      LOG_LEVEL = "info"
    }
  }
}

