### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kendra_index" "kendra_index" {
  name     = "kendra-index"
  role_arn = aws_iam_role.kendra_role.arn

  capacity_units {
    query_capacity_units   = 2
    storage_capacity_units = 5
  }

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }
}

resource "aws_kendra_data_source" "kendra_data_source" {
  index_id = aws_kendra_index.kendra_index.id
  name     = "kendra-data-source"
  type     = "WEBCRAWLER"
  role_arn = aws_iam_role.kendra_role.arn

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
      }
      proxy_configuration {
        host = "proxy.example.com"
        port = 8080
      }
    }
  }
}
```

