This Terraform program creates a basic Amazon Kendra index with the default Document Metadata Configuration Updates. It also sets up an IAM role required by the Kendra index. The IAM role allows the Kendra service to assume the role, which is necessary for Kendra to perform its operations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_kendra_index" "basic_kendra_index" {
  name       = "basic_kendra_index"
  role_arn   = aws_iam_role.kendra_role.arn

  document_metadata_configuration_updates {
    name = "_document_body"
    type = "STRING_VALUE"
  }

  document_metadata_configuration_updates {
    name = "_document_title"
    type = "STRING_VALUE"
  }
}
```

