The Terraform program defines a Route 53 zone named "primary.example.com" and configures a geolocation-based routing policy to route users to the nearest endpoint based on their location (US or EU). The program includes two VPCs, one for the US and one for the EU, and associates these VPCs with the Route 53 zone. Two Route 53 records are created, each with a geolocation routing policy specifying the US and EU continents, respectively.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "primary.example.com"
}

resource "aws_vpc" "us_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_vpc" "eu_vpc" {
  cidr_block = "10.1.0.0/16"
}

resource "aws_route53_zone_association" "us_association" {
  zone_id = aws_route53_zone.primary.zone_id
  vpc_id  = aws_vpc.us_vpc.id
  vpc_region = "us-east-1"
}

resource "aws_route53_zone_association" "eu_association" {
  zone_id = aws_route53_zone.primary.zone_id
  vpc_id  = aws_vpc.eu_vpc.id
  vpc_region = "eu-central-1"
}

resource "aws_route53_record" "geo_record_us" {
  name    = "geo_record"
  type    = "A"
  zone_id = aws_route53_zone.primary.zone_id

  geolocation_routing_policy {
    continent = "NA"
  }

  records = ["192.168.1.1"]  # Example IP address for US
}

resource "aws_route53_record" "geo_record_eu" {
  name    = "geo_record"
  type    = "A"
  zone_id = aws_route53_zone.primary.zone_id

  geolocation_routing_policy {
    continent = "EU"
  }

  records = ["192.168.2.1"]  # Example IP address for EU
}
```

This configuration ensures that users are routed to the nearest endpoint based on their location, with the US users being directed to the US VPC and EU users being directed to the EU VPC.

