### Description of the Terraform Program

This Terraform program defines an AWS EKS cluster named based on the provided `cluster_name` variable. It associates the EKS cluster with an IAM role that has the necessary permissions for managing the cluster. The EKS cluster is configured with VPC subnet IDs for networking. The program uses local-exec provisioners to manage kubectl configuration during the creation and destruction of the EKS cluster. Additionally, it ensures that IAM role permissions are handled properly before and after EKS cluster management.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "cluster_name" {
  type        = string
  description = "Name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "vpc_id" {
  type        = string
  description = "ID of the VPC where the EKS cluster will be deployed"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  type        = list(string)
  description = "List of subnet IDs for the EKS cluster"
  default     = ["subnet-12345678", "subnet-87654321", "subnet-abcdef12"]
}

resource "aws_iam_role" "eks_cluster_role" {
  name               = "${var.cluster_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = ["sts:AssumeRole", "sts:TagSession"]
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  lifecycle {
    create_before_destroy = true
  }

  provisioner "local-exec" {
    command = "aws eks update-kubeconfig --name ${var.cluster_name}"
    when    = create
  }

  provisioner "local-exec" {
    command = "kubectl config unset contexts.${self.name}"
    when    = destroy
  }
}
```

