### Description
This Terraform script provisions an AWS EKS cluster named "example" with the necessary IAM role and VPC settings. It includes dependencies on IAM role policy attachments for proper resource management during creation and deletion. The script also outputs the cluster's endpoint and the kubeconfig certificate authority data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "eks_cluster_example" {
  name = "eks-cluster-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sts:AssumeRole",
          "sts:TagSession"
        ]
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy Attachment for EKS Cluster
resource "aws_iam_role_policy_attachment" "eks_cluster_AmazonEKSClusterPolicy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_example.name
}

# Subnets for EKS Cluster
resource "aws_subnet" "subnet_az1" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = "vpc-12345678"  # Replace with your VPC ID
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

# EKS Cluster
resource "aws_eks_cluster" "example" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_example.arn

  vpc_config {
    subnet_ids = [
      aws_subnet.subnet_az1.id,
      aws_subnet.subnet_az2.id,
      aws_subnet.subnet_az3.id
    ]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_AmazonEKSClusterPolicy
  ]
}

# Outputs
output "cluster_endpoint" {
  description = "The endpoint of the EKS cluster"
  value       = aws_eks_cluster.example.endpoint
}

output "kubeconfig_certificate_authority_data" {
  description = "The kubeconfig certificate authority data of the EKS cluster"
  value       = base64decode(aws_eks_cluster.example.certificate_authority[0].data)
}
```

### Notes
- Replace `"vpc-12345678"` with your actual VPC ID.
- Ensure that the IAM role policy attachments are correctly configured based on your security requirements.
- The `depends_on` meta-argument ensures that the IAM role policy attachment is applied before the EKS cluster is created.

