### Description
This Terraform configuration sets up an AWS IAM role named `demo_eks` for an Amazon EKS cluster. The IAM role is configured to assume roles for EKS services and has policies attached for `AmazonEKSClusterPolicy` and `AmazonEKSVPCResourceController`. Additionally, it creates an AWS EKS cluster named `demo_eks` with specified VPC configurations, including subnets in three different availability zones (AZ1, AZ2, and AZ3). Proper dependency handling ensures that the IAM role permissions are correctly applied before the EKS cluster is created.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for EKS
resource "aws_iam_role" "demo_eks" {
  name = "demo_eks"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

# Attach AmazonEKSClusterPolicy to the IAM role
resource "aws_iam_role_policy_attachment" "demo_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.demo_eks.name
}

# Attach AmazonEKSVPCResourceController to the IAM role
resource "aws_iam_role_policy_attachment" "demo_eks_vpc_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.demo_eks.name
}

# Create a VPC
resource "aws_vpc" "demo_eks_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Create subnets in different availability zones
resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.demo_eks_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.demo_eks_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
