```hcl
provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "us-east-2"
  region = "us-east-2"
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_full_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonRedshiftFullAccess"
  role       = aws_iam_role.redshift_role.name
}

resource "aws_redshift_cluster" "primary_redshift_cluster" {
  cluster_identifier      = "primary-redshift-cluster"
  node_type               = "dc2.large"
  number_of_nodes         = 2
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = "SecurePassword123!"
  cluster_subnet_group_name = "default"
  iam_roles               = [aws_iam_role.redshift_role.arn]
}

resource "aws_redshift_cluster" "replica_redshift_cluster" {
  provider                = aws.us-east-2
  cluster_identifier      = "replica-redshift-cluster"
  node_type               = "dc2.large"
  number_of_nodes         = 2
  database_name           = "mydb"
  master_username         = "admin"
  master_password         = "SecurePassword123!"
  cluster_subnet_group_name = "default"
  iam_roles               = [aws_iam_role.redshift_role.arn]
  snapshot_copy {
    destination_region = "us-east-2"
  }
}

resource "aws_sns_topic" "redshift_events_topic" {
  name = "redshift-events-topic"
}

resource "aws_redshift_event_subscription" "redshift_event_subscription" {
  name          = "redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events_topic.arn
  source_ids    = [aws_redshift_cluster.primary_redshift_cluster.id]
  source_type   = "cluster"
  event_categories = ["configuration", "management", "monitoring", "security"]
}
```

### Explanation
1. **IAM Role and Policy Attachment**: An IAM role named `redshift-role` is created with a trust policy allowing Redshift to assume the role. The `AmazonRedshiftFullAccess` policy is attached to this role.
2. **Primary Redshift Cluster**: A Redshift cluster is set up in `us-east-1` using the IAM role.
3. **Replica Redshift Cluster**: A replica Redshift cluster is set up in `us-east-2`, also using the IAM role, and configured for snapshot replication.
4. **SNS Topic and Event Subscription**: An SNS topic is created to receive notifications, and an event subscription is set up to monitor events from the primary Redshift cluster, excluding the invalid `performance` category.

