### Description
This Terraform program creates an AWS Lambda function named "example_lambda" and a Lambda function URL for it. The Lambda function is configured with a basic role and a deployment package specified by a filename. The program also includes an example invocation of the Lambda function.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "example_lambda" {
  function_name = "example_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "path/to/deployment/package.zip"
}

resource "aws_lambda_function_url" "example_lambda_url" {
  function_name = aws_lambda_function.example_lambda.function_name
  authorization_type = "NONE"
}

resource "aws_lambda_invocation" "example_lambda_invocation" {
  function_name = aws_lambda_function.example_lambda.function_name
  input         = jsonencode({ "key1": "value1", "key2": "value2" })
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `lambda_execution_role` is created with a trust policy allowing Lambda to assume the role.
3. **IAM Role Policy Attachment**: The `AWSLambdaBasicExecutionRole` policy is attached to the IAM role to allow basic logging permissions.
4. **Lambda Function**: A Lambda function named `example_lambda` is created with the specified role, handler, runtime, and deployment package filename.
5. **Lambda Function URL**: A Lambda function URL is created for the `example_lambda` function with `NONE` authorization type.
6. **Lambda Invocation**: An example invocation of the `example_lambda` function is performed with a JSON input payload.

