```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_iam_role" "sagemaker_image_role" {
  name = "sagemaker-image-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  inline_policy {
    name = "sagemaker-image-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Action = [
            "s3:GetObject",
            "s3:ListBucket"
          ]
          Effect = "Allow"
          Resource = [
            "arn:aws:s3:::my-sagemaker-bucket",
            "arn:aws:s3:::my-sagemaker-bucket/*"
          ]
        }
      ]
    })
  }
}

resource "aws_sagemaker_image" "sagemaker_image" {
  image_name = "my-sagemaker-image"  # Updated to adhere to AWS naming conventions
  role_arn   = aws_iam_role.sagemaker_image_role.arn
}
