### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. The program includes the necessary resources such as subnets, a security group, and the MSK cluster itself. The subnets are created in three different availability zones (AZs) within a specified VPC. The security group allows inbound traffic on port 9092 for Kafka communication.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_id" {
  description = "The ID of the VPC where the MSK cluster will be deployed."
  default     = "vpc-12345678"  # Replace with a valid VPC ID
}

variable "cidr_block_az1" {
  description = "CIDR block for the subnet in AZ1."
  default     = "10.0.1.0/24"
}

variable "cidr_block_az2" {
  description = "CIDR block for the subnet in AZ2."
  default     = "10.0.2.0/24"
}

variable "cidr_block_az3" {
  description = "CIDR block for the subnet in AZ3."
  default     = "10.0.3.0/24"
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_az1
  availability_zone = "us-east-1a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_az2
  availability_zone = "us-east-1b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_az3
  availability_zone = "us-east-1c"
}

resource "aws_security_group" "msk_security_group" {
  name        = "msk_security_group"
  description = "Security group for MSK cluster"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_security_group.id]
    az_distribution = "DEFAULT"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
- **Variables**: The program uses variables for the VPC ID and CIDR blocks for the subnets. Default values are provided for these variables.
- **Subnets**: Three subnets are created in different availability zones (`us-east-1a`, `us-east-1b`, `us-east-1c`) within the specified VPC.
- **Security Group**: A security group is created to allow inbound traffic on port 9092 for Kafka communication.
- **MSK Cluster**: The MSK cluster is created with 3 broker nodes, using the specified subnets and security group. The instance type for the broker nodes is set to `t3.medium`.

