### Description
The Terraform program defines a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster in the `us-east-1` region, configured to log to an S3 bucket. The program includes the necessary resources such as an S3 bucket for logs, a VPC, subnets, security groups, and an IAM role. The MSK cluster is set up with a single broker node group in a specified subnet and security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket"
  acl    = "private"
}

resource "aws_s3_bucket_logging" "msk_bucket_logging" {
  bucket        = aws_s3_bucket.msk_logs_bucket.bucket
  target_bucket = aws_s3_bucket.msk_logs_bucket.bucket
  target_prefix = "logs/msk-"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_connector_role" {
  name = "msk_connector_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_sg.id]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = false
      }
      firehose {
        enabled = false
      }
      s3 {
        bucket  = aws_s3_bucket.msk_logs_bucket.bucket
        prefix  = "logs/msk-"
        enabled = true
      }
    }
  }
}
```

