      }
    ]
  })
}

# IAM Policy for Kinesis Firehose
resource "aws_iam_policy" "firehose_policy" {
  name = "msk-firehose-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.firehose_bucket.arn,
          "${aws_s3_bucket.firehose_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

# S3 Bucket for Kinesis Firehose
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "msk-firehose-bucket-${random_string.suffix.result}"
}

# Random String for S3 Bucket Name
resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This configuration includes the `random` provider, which is necessary for generating the random suffix for the S3 bucket name. This should resolve the error related to the missing `random_string` provider.

