### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with encryption at rest. The program includes the necessary resources such as subnets, security groups, and a KMS key. The MSK cluster is configured to use these resources to ensure secure and encrypted data storage.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.example.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_kms_key" "msk_kms_key" {
  description             = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 10
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = "3.2.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_sg.id]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }
}
```

This Terraform configuration sets up a VPC with three subnets across different availability zones, a security group to control inbound and outbound traffic, a KMS key for encryption at rest, and an MSK cluster configured to use these resources. The MSK cluster is set to use the specified Kafka version and instance type, with encryption enabled using the KMS key.

