### Description

This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with JMX Exporter and Node Exporter enabled. The program includes the necessary resources such as subnets, security groups, and the MSK cluster itself. The MSK cluster is configured to use three broker nodes, each with an instance type of `kafka.m5.4xlarge`. The cluster is set up in a VPC with three subnets across different availability zones, and a security group is created to control inbound and outbound traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the MSK cluster will be deployed."
  default     = "vpc-12345678"
}

variable "cidr_block_az1" {
  description = "CIDR block for the first subnet."
  default     = "10.0.1.0/24"
}

variable "cidr_block_az2" {
  description = "CIDR block for the second subnet."
  default     = "10.0.2.0/24"
}

variable "cidr_block_az3" {
  description = "CIDR block for the third subnet."
  default     = "10.0.3.0/24"
}

resource "aws_subnet" "subnet_az1" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_az1
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_az2
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "subnet_az3" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_az3
  availability_zone = "us-west-2c"
}

resource "aws_security_group" "msk_security_group" {
  name        = "msk_security_group"
  description = "Security group for MSK cluster"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = "2.7.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    instance_type  = "kafka.m5.4xlarge"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}
```

This Terraform configuration sets up a managed MSK cluster with JMX Exporter and Node Exporter enabled, ensuring that the cluster is properly configured with the necessary subnets and security groups.

