### Description
This Terraform program creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. It includes the necessary VPC subnets, security groups, and configurations required for the MSK cluster to operate within a secure network environment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "msk-vpc"
  }
}

# Create subnets in different availability zones
resource "aws_subnet" "subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "msk-subnet-az1"
  }
}

resource "aws_subnet" "subnet_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"
  tags = {
    Name = "msk-subnet-az2"
  }
}

# Create a security group
resource "aws_security_group" "security_group" {
  vpc_id = aws_vpc.main.id
  name   = "msk-security-group"

  ingress {
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# Create the serverless MSK cluster
resource "aws_msk_serverless_cluster" "serverless_msk_cluster" {
  cluster_name = "serverless_msk_cluster"

  vpc_config {
    subnet_ids         = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id]
    security_group_ids = [aws_security_group.security_group.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  tags = {
    Name = "serverless_msk_cluster"
  }
}
```

This Terraform configuration sets up a VPC with two subnets in different availability zones, a security group with appropriate ingress and egress rules, and a serverless MSK cluster configured to use these resources. The MSK cluster is secured using IAM authentication.

