Description:
The Terraform program defines a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. It includes the necessary IAM role and policy attachments required for the MSK cluster to operate. The configuration specifies the region, cluster name, client authentication settings, and VPC configuration.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "msk_role" {
  name = "msk-serverless-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_role.name
}

resource "aws_msk_serverless_cluster" "serverless_msk_cluster" {
  cluster_name = "serverless_msk_cluster"

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210", "subnet-01a2b3c4d5e6f7g8h"]
  }

  timeouts {
    create = "60m"
    delete = "60m"
  }
}
```

This configuration removes the unsupported `kafka_version` attribute and ensures that the MSK serverless cluster is properly set up with the required IAM roles and policies.

