### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify a valid AWS region
}

resource "aws_kms_key" "example_kms_key" {
  description             = "Encryption key for DynamoDB table"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_dynamodb_table" "example_dynamodb_table" {
  name           = "example_dynamodb_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.example_kms_key.arn
  }
}
```

