### Description
The Terraform program creates two AWS S3 buckets: one for storing source objects (`source_bucket`) and another for storing the inventory reports (`inventory_bucket`). It configures a weekly CSV inventory report for the `source_bucket`, which includes all current object versions and stores the report in the `inventory_bucket`. Additionally, it sets up an IAM role and policy to allow the S3 service to write inventory reports to the `inventory_bucket`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "source_bucket" {
  bucket = "my-source-bucket-${random_string.suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket" "inventory_bucket" {
  bucket = "my-inventory-bucket-${random_string.suffix.result}"
  acl    = "private"
}

resource "aws_s3_bucket_inventory" "source_bucket_inventory" {
  bucket = aws_s3_bucket.source_bucket.id
  name   = "weekly-csv-inventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format = "CSV"
      bucket_arn = aws_s3_bucket.inventory_bucket.arn
      prefix = "inventories/"
    }
  }
}

resource "aws_iam_role" "dlm_lifecycle_role" {
  name = "s3-inventory-role-${random_string.suffix.result}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "dlm_lifecycle_policy" {
  name = "s3-inventory-policy-${random_string.suffix.result}"
  role = aws_iam_role.dlm_lifecycle_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.inventory_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This configuration ensures that the S3 inventory report is generated weekly and stored in the designated inventory bucket, with the necessary IAM permissions in place.

