```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = "codebuild-output-bucket-${var.environment}"
  acl    = "private"
}

resource "aws_vpc" "codebuild_vpc" {
