### Description

This Terraform program sets up an AWS service that allows users to upload cat pictures and retrieve random cat pictures using API Gateway and S3. The program includes the following components:

1. **S3 Bucket**: A private S3 bucket named `cat-pictures-bucket` where cat pictures will be stored.
2. **API Gateway REST API**: A REST API named `cat-pictures-api` that exposes two endpoints:
   - `/upload`: Allows users to upload cat pictures.
   - `/random`: Provides a random cat picture.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.region}:s3:path/${aws_s3_bucket.cat_pictures_bucket.bucket}/"
}

resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random"
}

resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  type                    = "AWS_PROXY"
  integration_http_method = "GET"
  uri                     = "arn:aws:apigateway:${var.region}:s3:path/${aws_s3_bucket.cat_pictures_bucket.bucket}/"
}

variable "environment" {
  description = "Environment name to append to the S3 bucket name"
  default     = "dev"
}

variable "region" {
  description = "AWS region to deploy the resources"
  default     = "us-west-2"
}
```

### Explanation

- **S3 Bucket**: The `aws_s3_bucket` resource creates a private S3 bucket where cat pictures will be stored. The bucket name is made unique by appending the environment name.
- **API Gateway REST API**: The `aws_api_gateway_rest_api` resource creates a REST API with the name `cat-pictures-api`.
- **API Gateway Resources and Methods**: Two resources (`upload` and `random`) and their corresponding methods (`POST` and `GET`) are defined under the API.
- **API Gateway Integrations**: The integrations for both methods are set up to proxy requests to the S3 bucket.
- **Variables**: Two variables, `environment` and `region`, are defined with default values to allow customization of the deployment environment and region.

