### Description
This Terraform program sets up an AWS infrastructure to host a web service that allows users to upload cat pictures and retrieve random cat pictures. The service uses AWS API Gateway to handle HTTP requests, AWS S3 to store the cat pictures, and AWS Lambda functions to process the uploads and retrieve random images.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# S3 Bucket to store cat pictures
resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${var.environment}"
  acl    = "private"
}

# IAM Role for Lambda functions
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda functions to access S3
resource "aws_iam_policy" "lambda_s3_access_policy" {
  name        = "lambda-s3-access-policy-${var.environment}"
  description = "Policy to allow Lambda functions to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.cat_pictures_bucket.arn}/*",
          aws_s3_bucket.cat_pictures_bucket.arn
        ]
      }
    ]
  })
}

# Attach the S3 access policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_s3_access" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_s3_access_policy.arn
}

# Lambda function to upload cat pictures
resource "aws_lambda_function" "upload_cat_picture" {
  function_name = "upload-cat-picture-${var.environment}"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "upload_cat_picture.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

# Lambda function to get a random cat picture
resource "aws_lambda_function" "get_random_cat_picture" {
  function_name = "get-random-cat-picture-${var.environment}"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "get_random_cat_picture.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

# API Gateway REST API
resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api-${var.environment}"
  description = "API for uploading and retrieving cat pictures"
}

# API Gateway Resource for upload
resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

# API Gateway Resource for random
resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random"
}

# API Gateway Method for upload
resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

# API Gateway Method for random
resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

# API Gateway Integration for upload
resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.upload_cat_picture.invoke_arn
}

# API Gateway Integration for random
resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  integration_http_method = "GET"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.get_random_cat_picture.invoke_arn
}

# API Gateway Deployment
resource "aws_api_gateway_deployment" "cat_pictures_deployment" {
  depends_on = [
    aws_api_gateway_integration.upload_integration,
    aws_api_gateway_integration.random_integration
  ]

  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"
}

# Variable for environment
variable "environment" {
  description = "Environment name for resources"
  default     = "dev"
}
```

This Terraform configuration sets up the necessary AWS resources to create a web service for uploading and retrieving cat pictures. It includes an S3 bucket for storage, IAM roles and policies for Lambda functions, and API Gateway to handle HTTP requests. The Lambda functions are configured to interact with the S3 bucket, and the API Gateway is set up to route requests to the appropriate Lambda functions.

