### Description
This Terraform program sets up an AWS infrastructure to run a piece of code every day at 7 UTC using AWS EventBridge. The program includes the following components:

1. **AWS CloudWatch Event Rule**: A scheduled event rule that triggers at 7 UTC every day.
2. **AWS Lambda Function**: A Lambda function that contains the code to be executed.
3. **AWS CloudWatch Event Target**: A target that links the event rule to the Lambda function.
4. **AWS IAM Role**: An IAM role that grants the Lambda function necessary permissions.
5. **AWS IAM Policy**: A basic execution policy attached to the IAM role.
6. **AWS IAM Role Policy Attachment**: Attaches the IAM policy to the IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Policy for Lambda execution
resource "aws_iam_policy" "lambda_basic_execution_policy" {
  name        = "lambda_basic_execution_policy"
  description = "Basic execution policy for Lambda functions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# IAM Role for Lambda execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy" {
  policy_arn = aws_iam_policy.lambda_basic_execution_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# Lambda function that will be triggered
resource "aws_lambda_function" "code_runner_lambda" {
  function_name = "code_runner_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function_payload.zip"
}

# CloudWatch Event Rule to trigger the Lambda function daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_code_runner" {
  name                = "daily_code_runner"
  schedule_expression = "cron(0 7 * * ? *)"
}

# CloudWatch Event Target to link the rule to the Lambda function
resource "aws_cloudwatch_event_target" "lambda_target" {
  rule      = aws_cloudwatch_event_rule.daily_code_runner.name
  target_id = "RunCodeDaily"
  arn       = aws_lambda_function.code_runner_lambda.arn
}
```

