This Terraform program sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge, AWS Lambda, and IAM roles. The program includes an EventBridge rule that triggers a Lambda function at the specified time. The Lambda function is granted permission to be invoked by EventBridge through an IAM role and a Lambda permission.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_lambda_function" "daily_task_lambda" {
  function_name = "daily_task_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "path/to/your/lambda/code.zip"

  environment {
    variables = {
      # Add any environment variables your Lambda function needs
    }
  }
}

resource "aws_cloudwatch_event_rule" "daily_7utc_rule" {
  name                = "daily_7utc_rule"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_task_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_7utc_rule.arn
}

