### Description
The Terraform program below sets up the infrastructure for a video streaming site using AWS CloudFront and AWS S3. It creates an S3 bucket to store the video content and a CloudFront distribution to serve the content globally. The CloudFront distribution is configured to allow GET, HEAD, and OPTIONS methods, and it caches GET and HEAD requests. The S3 bucket is publicly accessible, which is necessary for CloudFront to serve the content.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket"
  acl    = "public-read"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Content Distribution"
  default_root_object = "index.html"

  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id   = "myS3Origin"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "myS3Origin"
    viewer_protocol_policy = "allow-all"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}
```

This Terraform configuration will create an S3 bucket named `video-content-bucket` with public read access and a CloudFront distribution that serves content from this bucket. The CloudFront distribution is configured to handle GET, HEAD, and OPTIONS requests and caches GET and HEAD requests. The distribution uses the default SSL certificate provided by CloudFront.

