### Description
This Terraform configuration sets up the infrastructure for a video streaming site using AWS CloudFront, AWS Route53, and AWS S3. The configuration includes creating an S3 bucket to store video content, setting up a CloudFront distribution to serve the content globally, and configuring a Route53 DNS record to point to the CloudFront distribution. Additionally, IAM roles and policies are created to ensure secure access between CloudFront and the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity ${aws_cloudfront_origin_access_identity.origin_access_identity.cloudfront_access_identity_path}"
        }
        Action = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role" "cloudfront_origin_access_role" {
  name = "cloudfront-origin-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "cloudfront_origin_access_policy" {
  name        = "cloudfront-origin-access-policy"
  description = "Policy allowing CloudFront to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_cloudfront_policy_to_role" {
  policy_arn = aws_iam_policy.cloudfront_origin_access_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_role.name
}

resource "aws_cloudfront_origin_access_identity" "origin_access_identity" {
  comment = "Origin access identity for CloudFront to access S3 bucket"
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled = true

  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id   = "myS3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.origin_access_identity.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods    = ["GET", "HEAD"]
    target_origin_id  = "myS3Origin"
    viewer_protocol_policy = "redirect-to-https"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_route53_record" "video_content_dns" {
  name    = "video.streaming.example.com"
  type    = "A"
  zone_id = "Z1D633PJN98FT9"  # Replace with your actual hosted zone ID

  alias {
    name                   = aws_cloudfront_distribution.video_content_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_content_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}
```

This configuration ensures that the video content is securely stored in an S3 bucket, served globally via CloudFront, and accessible through a custom domain managed by Route53. The IAM roles and policies ensure that CloudFront has the necessary permissions to access the S3 bucket.

