### Description of the Terraform Program

The Terraform program defines the infrastructure for a video streaming site that includes multiple servers to balance load using AWS Load Balancing. The program creates the following resources:

1. **AWS VPC**: A Virtual Private Cloud to contain all the resources.
2. **AWS Subnets**: Two public subnets in different availability zones.
3. **AWS Application Load Balancer (ALB)**: An application load balancer to distribute incoming traffic across the servers.
4. **AWS Target Group**: A target group associated with the load balancer to manage the health and routing of traffic to the servers.
5. **AWS EC2 Instances**: Two EC2 instances running in the public subnets, which serve as the backend servers for the video streaming site.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = element(aws_subnet.public.*.id, count.index)
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_instance" "video_streaming_server" {
  count         = 2
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  subnet_id     = element(aws_subnet.public.*.id, count.index)

  tags = {
    Name = "video-streaming-server-${count.index}"
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_tg_attachment" {
  count            = 2
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = element(aws_instance.video_streaming_server.*.id, count.index)
  port             = 80
}
