### Description

This Terraform program provisions a secure PostgreSQL database instance within a specified AWS VPC. It leverages AWS services like RDS, subnets, and KMS for encryption. The program sets up a custom parameter group for PostgreSQL settings and a security group to manage access. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key. The database instance is configured with an instance class of "db.t3.micro" and a backup retention period of 7 days.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the database will be deployed."
  default     = "vpc-12345678"
}

variable "subnet_cidr_block" {
  description = "The CIDR block for the subnet."
  default     = "10.0.1.0/24"
}

variable "db_name" {
  description = "The name of the database."
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database."
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database."
  default     = "securepassword123"
}

resource "aws_kms_key" "postgres_kms_key" {
  description             = "KMS key for encrypting the PostgreSQL database"
  deletion_window_in_days = 10
}

resource "aws_db_subnet_group" "postgres_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.postgres_subnet.id]
}

resource "aws_subnet" "postgres_subnet" {
  vpc_id                  = var.vpc_id
  cidr_block              = var.subnet_cidr_block
  map_public_ip_on_launch = false
}

resource "aws_security_group" "postgres_sg" {
  name        = "postgres-sg"
  description = "Security group for PostgreSQL database"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this for security purposes
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "postgres_custom_param_group" {
  name   = "postgres-custom-param-group"
  family = "postgres12"

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }
}

resource "aws_db_instance" "postgres_db_instance" {
  identifier              = "postgres-db-instance"
  engine                  = "postgres"
  engine_version          = "12.11"
  instance_class          = "db.t3.micro"
  allocated_storage       = 20
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.postgres_kms_key.arn
  db_subnet_group_name    = aws_db_subnet_group.postgres_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.postgres_sg.id]
  multi_az                = true
  backup_retention_period = 7
  username                = var.db_username
  password                = var.db_password
  db_name                 = var.db_name
}
```

