### Description
This Terraform program sets up a PostgreSQL 15 instance on AWS RDS within specific public subnets for running Airbyte connector test cases. The database uses managed settings for low maintenance, skips the final snapshot, and applies changes immediately. The program includes necessary IAM roles and security groups to ensure restricted access.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "allocated_storage" {
  description = "The allocated storage size for the RDS instance"
  type        = number
  default     = 20
}

variable "username" {
  description = "The database username"
  type        = string
  default     = "airbyte_user"
}

variable "password" {
  description = "The database password"
  type        = string
  sensitive   = true
  default     = "secure_password123"
}

variable "db_subnet_group_name" {
  description = "The name of the DB subnet group"
  type        = string
  default     = "airbyte-subnet-group"
}

variable "vpc_id" {
  description = "The ID of the VPC where the RDS instance will be created"
  type        = string
  default     = "vpc-12345678"
}

resource "aws_db_subnet_group" "airbyte_subnet_group" {
  name       = var.db_subnet_group_name
  subnet_ids = ["subnet-12345678", "subnet-87654321"]
  tags = {
    Name = "Airbyte Subnet Group"
  }
}

resource "aws_security_group" "airbyte_sg" {
  name        = "airbyte-sg"
  description = "Security group for Airbyte PostgreSQL RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Restrict this in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "airbyte_rds_role" {
  name = "airbyte-rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "airbyte_rds_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.airbyte_rds_role.name
}

resource "aws_db_instance" "airbyte_postgres" {
  engine               = "postgres"
  engine_version       = "15"
  instance_class       = "db.t3.medium"
  allocated_storage    = var.allocated_storage
  username             = var.username
  password             = var.password
  db_subnet_group_name = aws_db_subnet_group.airbyte_subnet_group.name
  vpc_security_group_ids = [aws_security_group.airbyte_sg.id]
  iam_database_authentication_enabled = true
  skip_final_snapshot  = true
  apply_immediately    = true
  parameter_group_name = "default.postgres15"
}
```

