### Description
This Terraform program sets up an AWS environment with a main VPC, two subnets across different availability zones, and a security group to allow database access. It also configures a MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "db_security_group" {
  name        = "db-security-group"
  description = "Allow database access"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "main_db_subnet_group" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
}

resource "aws_db_instance" "mysql_db_instance" {
  identifier              = "my-mysql-db"
  instance_class          = "db.t3.micro"
  engine                  = "mysql"
  engine_version          = "8.0"
  allocated_storage       = 20
  username                = "admin"
  password                = "password"
  publicly_accessible     = true
  db_subnet_group_name    = aws_db_subnet_group.main_db_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.db_security_group.id]
}

output "database_endpoint" {
  value = aws_db_instance.mysql_db_instance.endpoint
}
```

