### Description
The Terraform program sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. It specifies details such as the engine version, instance size, storage, and networking configurations. The database instance allows major version upgrades, automatically performs minor version upgrades, and is not publicly accessible. Additionally, an IAM role is created for the database proxy, and a security group is configured to restrict inbound traffic to the database instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "db_instance_class" {
  description = "Instance class for the RDS instance"
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage for the RDS instance in GB"
  default     = 20
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  default     = "securepassword123"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "db_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Allow access from within the VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "db_proxy_role" {
  name = "db_proxy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_db_instance" "postgres_db_instance" {
  engine               = "postgres"
  engine_version       = "13.6"  # Example version, can be updated
  instance_class       = var.db_instance_class
  allocated_storage    = var.allocated_storage
  db_name              = var.db_name
  username             = var.db_username
  password             = var.db_password
  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
  allow_major_version_upgrade = true
  auto_minor_version_upgrade  = true
  publicly_accessible  = false
  iam_database_authentication_enabled = true
}

resource "aws_db_subnet_group" "main" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.db_subnet.id]
}
```

This configuration ensures that the PostgreSQL database instance is set up correctly within the specified VPC and subnet, with the necessary security and IAM configurations.

