### Description
This Terraform program sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management. It includes the necessary components such as a VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The configuration ensures that all resources are properly interconnected and configured to meet the specified requirements.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Create a Subnet
resource "aws_subnet" "aurora_subnet" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Create a Security Group
resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  name   = "aurora-sg"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM Role for the DB Proxy
resource "aws_iam_role" "aurora_proxy_role" {
  name = "aurora-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# Create a Secrets Manager Secret for Aurora Credentials
resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"
}

# Create an Aurora MySQL Cluster
resource "aws_rds_cluster" "aurora_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.02.0"
  cluster_identifier  = "aurora-cluster"
  master_username     = "admin"
  master_password     = "securepassword123"
  db_subnet_group_name = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
}

# Create a DB Subnet Group
resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet.id]
}

# Create a DB Proxy
resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.aurora_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.aurora_subnet.id]
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = "admin"
  }
