### Description
This Terraform program creates an S3 bucket, configures a lifecycle rule to transition objects to Amazon S3 Glacier after 30 days, sets up an SNS topic for notifications, and creates an S3 Glacier vault with notifications configured to send messages to the SNS topic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-s3-bucket"
  acl    = "private"
}

resource "aws_s3_bucket_lifecycle_configuration" "my_s3_bucket_lifecycle" {
  bucket = aws_s3_bucket.my_s3_bucket.id

  rule {
    id     = "transition_to_glacier"
    status = "Enabled"

    transition {
      days          = 30
      storage_class = "GLACIER"
    }
  }
}

resource "aws_sns_topic" "my_sns_topic" {
  name = "my-sns-topic"
}

resource "aws_glacier_vault" "my_glacier_vault" {
  name = "my-glacier-vault"

  notification {
    events     = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
    sns_topic  = aws_sns_topic.my_sns_topic.arn
  }
}
```

This configuration ensures that the S3 bucket has a lifecycle rule to transition objects to Glacier after 30 days, and the Glacier vault is set up to notify the specified SNS topic on certain events.

