### Description
This Terraform program creates an S3 Glacier vault named "MyArchive" and configures a Vault Lock on it. The Vault Lock is set to deny all actions, ensuring that the contents of the vault cannot be modified or deleted. Additionally, an SNS topic named "glacier-sns-topic" is created to receive notifications for specific events related to the Glacier vault, such as the completion of archive retrievals and inventory retrievals.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_sns_topic" "glacier_sns_topic" {
  name = "glacier-sns-topic"
}

resource "aws_glacier_vault" "my_glacier_vault" {
  name = "MyArchive"

  notification {
    events     = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
    sns_topic  = aws_sns_topic.glacier_sns_topic.arn
  }
}

resource "aws_glacier_vault_lock" "my_glacier_vault_lock" {
  vault_name = aws_glacier_vault.my_glacier_vault.name
  complete_lock = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Principal = "*"
        Action   = "glacier:*"
        Resource = "*"
      }
    ]
  })
}
```

