data "aws_iam_policy_document" "my_archive_policy" {
  statement {
    sid     = "add-read-only-perm"
    effect  = "Allow"
    actions = ["glacier:GetJobOutput", "glacier:ListJobs", "glacier:DescribeVault", "glacier:InitiateJob", "glacier:ListMultipartUploads", "glacier:AbortMultipartUpload", "glacier:CompleteMultipartUpload", "glacier:UploadMultipartPart"]
