### Description
The Terraform program defines an internal-facing Network Load Balancer (NLB) within an AWS VPC. The NLB is configured to use private IP addresses by mapping subnets and associating Elastic IPs (EIPs) with them. The VPC and subnets are created within the `us-west-2` region.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet1" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet2" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_eip" "eip1" {
  vpc = true
}

resource "aws_eip" "eip2" {
  vpc = true
}

resource "aws_lb" "internal_lb" {
  name               = "internal-lb"
  internal           = true
  load_balancer_type = "network"

  subnet_mapping {
    subnet_id      = aws_subnet.subnet1.id
    allocation_id  = aws_eip.eip1.id
  }

  subnet_mapping {
    subnet_id      = aws_subnet.subnet2.id
    allocation_id  = aws_eip.eip2.id
  }
}
```

### Explanation of Changes
1. **Name Attribute Fix**: The `name` attribute of the `aws_lb` resource was changed from `"internal_lb"` to `"internal-lb"` to comply with the requirement that names must only contain alphanumeric characters and hyphens.

