LLM Output #0:
### Description
This Terraform program creates an Application Load Balancer (ALB) with a listener that performs a redirect action. The ALB is configured to listen on port 80 using the HTTP protocol and redirects traffic to a specified target group. The program includes necessary resources such as the load balancer, listener, and target group. It also sets up the required subnets and security groups.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a VPC
resource "aws_vpc" "my_vpc" {
  cidr_block = "10.0.0.0/16"
}

# Define two subnets
resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

# Define a security group
resource "aws_security_group" "my_sg" {
  name        = "my_sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.my_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Define the Application Load Balancer
resource "aws_lb" "my_load_balancer" {
  name               = "my-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.my_sg.id]
  subnets            = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
}

# Define the listener with a redirect action
resource "aws_lb_listener" "my_load_balancer_listener" {
  load_balancer_arn = aws_lb.my_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "redirect"
    redirect {
      protocol       = "HTTPS"
      port           = "443"
      status_code    = "HTTP_301"
    }
  }
}
```

This Terraform configuration sets up an Application Load Balancer in the `us-west-2` region with two subnets and a security group that allows HTTP traffic. The listener on port 80 uses a redirect action to forward traffic to HTTPS on port 443 with a 301 status code.

