### Description
This Terraform program defines an Application Load Balancer (ALB) with an HTTP listener that uses Cognito authentication. The program includes the necessary resources for a Cognito User Pool, User Pool Client, and User Pool Domain. The ALB listener is configured to authenticate users using the Cognito User Pool.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "front_end" {
  name               = "front-end-alb"
  load_balancer_type = "application"
  subnets            = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]  # Replace with actual subnet IDs
  security_groups      = ["sg-0123456789abcdef0"]  # Replace with actual security group ID
}

resource "aws_lb_listener" "front_end" {
  load_balancer_arn = aws_lb.front_end.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "authenticate-cognito"
    order            = 1

    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.client.id
      user_pool_domain    = aws_cognito_user_pool_domain.domain.domain
    }
  }
}

resource "aws_cognito_user_pool" "pool" {
  name = "my-user-pool"
}

resource "aws_cognito_user_pool_client" "client" {
  name         = "my-app-client"
  user_pool_id = aws_cognito_user_pool.pool.id
  generate_secret = true
}

resource "aws_cognito_user_pool_domain" "domain" {
  domain       = "myappdomain"
  user_pool_id = aws_cognito_user_pool.pool.id
}
```

### Notes
- **Subnets and Security Groups**: Replace the placeholder subnet and security group IDs with actual IDs from your AWS account.
- **Cognito Configuration**: The Cognito User Pool, User Pool Client, and User Pool Domain are configured with basic settings. You may need to adjust these settings based on your specific requirements.
- **Region**: The provider is set to `us-west-2`. You can change this to any other valid AWS region as needed.

