### Description
The Terraform program defines an Application Load Balancer (ALB) with a target group in the AWS cloud. The ALB is configured to listen on port 80 for HTTP traffic and forward requests to the target group. The target group is associated with a VPC and has a health check configured to ensure the availability of the targets. The necessary security group is also created to allow HTTP traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index}"
  }
}

data "aws_availability_zones" "available" {}

resource "aws_lb" "example_lb" {
  name               = "example-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = aws_subnet.public[*].id

  security_groups = [aws_security_group.lb_sg.id]

  tags = {
    Name = "example-alb"
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.example_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.example_lb_target_group.arn
  }
}

resource "aws_lb_target_group" "example_lb_target_group" {
  name     = "example-lb-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    interval            = 30
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example_lb_target_group"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "example-lb-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-lb-sg"
  }
}
```

This configuration creates a VPC, two public subnets, an Application Load Balancer, a listener on port 80, a target group, and a security group to allow HTTP traffic. The target group's name has been modified to ensure it only contains alphanumeric characters and hyphens, as required by AWS.

