LLM Output #0:
### Description

This Terraform configuration sets up an Application Load Balancer (ALB) with an associated Target Group in the AWS cloud. The ALB listens on port 80 for HTTP traffic and responds with a "Hello, World!" message. The Target Group is configured to check the health of instances on port 80 using HTTP.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "lb_sg" {
  name        = "lb_sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "alb_example" {
  name               = "alb_example"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public_subnet.id]

  listener {
    protocol = "HTTP"
    port     = 80

    default_action {
      type             = "fixed-response"
      fixed_response {
        content_type = "text/plain"
        message_body = "Hello, World!"
        status_code  = "200"
      }
    }
  }
}

resource "aws_lb_target_group" "alb_target_group_example" {
  name     = "alb-target-group-example"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id
  target_type = "instance"

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}
```

### Explanation of Changes

1. **Listener Block**: The `listener` block was correctly placed inside the `aws_lb` resource.
2. **Target Group Name**: The `name` attribute of the `aws_lb_target_group` resource was changed to "alb-target-group-example" to ensure it only contains alphanumeric characters and hyphens.

This configuration should now be deployable with Terraform version ~> 1.9.8 and the AWS provider version ~> 5.75.

