Description:
The Terraform program sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled, an internet gateway, and a route table for outbound internet access, all tagged with a variable name. The VPC is configured with a specified CIDR block, and the internet gateway is attached to the VPC. A route table is created and associated with the VPC, and a route is added to allow outbound internet access via the internet gateway.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "dedicated-vpc"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

resource "aws_vpc" "dedicated_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "dedicated"
  tags                 = merge(var.tags, { Name = var.vpc_name })
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.dedicated_vpc.id
  tags   = merge(var.tags, { Name = var.vpc_name })
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.dedicated_vpc.id
  tags   = merge(var.tags, { Name = var.vpc_name })
}

resource "aws_route" "route_to_internet" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id
}
```

This configuration ensures that all resources are properly tagged with the provided tags and the VPC name. The `merge` function is used to combine the user-provided tags with a default tag for the `Name` attribute.

