The Terraform program sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled, an internet gateway, and a route table for outbound internet access, all tagged with a variable name. The VPC uses a default CIDR block of "10.0.0.0/16" and is located in the "us-west-2" region. The program includes variables for the VPC name and CIDR block, with default values provided. Tags are applied to all resources using a map variable.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "my-dedicated-vpc"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "tags" {
  description = "Tags to apply to the resources"
  type        = map(string)
  default     = {}
}

resource "aws_vpc" "dedicated_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "dedicated"
  tags                 = merge(var.tags, { Name = var.vpc_name })
}

resource "aws_internet_gateway" "internet_gateway" {
  vpc_id = aws_vpc.dedicated_vpc.id
  tags   = merge(var.tags, { Name = var.vpc_name })
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.dedicated_vpc.id
  tags   = merge(var.tags, { Name = var.vpc_name })
}

resource "aws_route" "route_to_internet" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.internet_gateway.id
}
```

This configuration ensures that all resources are properly tagged with the variable name and that the VPC is set up with the specified attributes. The `merge` function is used to combine the user-provided tags with a default tag containing the VPC name.

